local({
  x <- coalesce(parent_limit_screen, parent_limit_tv)
  case_when(x %in% 2:4 ~ "TRUE", x == 1 ~ "FALSE")
})

local({
  x <- coalesce(parent_limit_screen, parent_limit_tv)
  if_else(x %in% 1:4, as.numeric(x), NA_real_)
})

local({
  tv <- "MTF parent-limit item (adolescent report; TV); restrictive: 'Limit the amount of time you can spend watching TV', 1 of 1 item, 1-4 item scoring (range 1-4), single item"
  screen <- "MTF parent-limit item (adolescent report; screen time: video games, social media, TV and movies); restrictive: 'Limit the amount of your screen time', 1 of 1 item, 1-4 item scoring (range 1-4), single item"
  if_else(data_year <= 2020, tv, screen)
})

local({
  items_2023 <- "self: MTF past-year school engagement items (study items, no published scoring), 13 of 13 items, 1-5 item scoring (never to always or almost always; range 1-5), mean; 'hate being in school', 'get in trouble at school', 'just act as if I am working' and 'feel bored in school' reversed (6 - x); complete-case"
  items_12 <- "self: MTF past-year school items (study items, no published scoring), 4 of 9 items (enjoy being in school, hate being in school, try to do your best work, fail to complete or turn in your assignments), 1-5 item scoring (never to almost always; range 1-5), mean; 'hate being in school' and 'fail to complete or turn in your assignments' reversed (6 - x); complete-case"
  items_8_10 <- "self: MTF past-year school items (study items, no published scoring), 5 of 7 items (enjoy being in school, hate being in school, try to do your best work, find your school work interesting, fail to complete or turn in your assignments), 1-5 item scoring (never to almost always; range 1-5), mean; 'hate being in school' and 'fail to complete or turn in your assignments' reversed (6 - x); complete-case"
  case_when(data_year >= 2023 ~ items_2023, grade == 12 ~ items_12, .default = items_8_10)
})

local({
  worst <- pmax(na_if(as.numeric(fight_gang), -9), na_if(as.numeric(serious_fight), -9), na.rm = TRUE)
  case_when(worst >= 2 ~ "TRUE", worst == 1 ~ "FALSE")
})

local({
  worst <- pmax(na_if(as.numeric(skip_days_4wk), -9), na_if(as.numeric(skip_class_4wk), -9), na.rm = TRUE)
  case_when(worst >= 2 ~ "TRUE", worst == 1 ~ "FALSE")
})

local({
  worst <- pmax(
    na_if(as.numeric(steal_under50), -9),
    na_if(as.numeric(steal_over50), -9),
    na_if(as.numeric(steal_shoplift), -9),
    na.rm = TRUE
  )
  case_when(worst >= 2 ~ "TRUE", worst == 1 ~ "FALSE")
})

local({
  worst <- pmax(
    na_if(as.numeric(damage_school_property), -9),
    na_if(as.numeric(damage_work_property), -9),
    na_if(as.numeric(arson), -9),
    na.rm = TRUE
  )
