local({
  inches <- 52 + if_else(height_code %in% 1:27, height_code, NA_real_)
  wmid <- c(80, seq(83, 138, by = 5), seq(145.5, 255.5, by = 10), 261)
  pounds <- wmid[if_else(weight_code %in% 1:26, weight_code, NA_real_)]
  703 * pounds / inches^2
})
